head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > autoResizeEmbeddedInput]<br/>embeddedInput=true 인 Column 의 Input 창 크기를 자동으로 조정할지 설정합니다.",
    "validation" : [
        "true 설정 시, td 요소의 크기가 변경되면 Cell 의 Input 창 크기도 자동으로 조정됩니다.",
        "true 설정 시, inputType='text','secret','calendar' 인 Column 에만 적용됩니다.",
        "false 설정 시, Input 창이 활성화 될때 td 요소에 맞게 크기가 조정됩니다.",
        "미설정 시, Input 창이 활성화 될때 td 요소에 맞게 크기가 조정됩니다.",
        "accessibility=true 이면 senseReader=true, autoResizeEmbeddedInput=true 가 강제 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList(gdl_boolean) 생성 (con_autoResizeEmbeddedInput 의 data:gdl_boolean 바인딩 전제)
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - 본 Property 는 embeddedInput=true 인 Column 환경에서만 의미가 있으므로 col1~col4 모두 embeddedInput=true 로 구성
//  - autoResize 가 적용되는 inputType(text, secret, calendar) 을 col1/col2/col3 에 배치, col4 는 추가 text(embedded) 비교용
//  - con_autoResizeEmbeddedInput(gdl_boolean) : 라벨이 실제 값 → getText() 사용. 빈값('') 이면 속성 자체 미부여(엔진 기본 false)
//  - con_accessibility : accessibility=true 면 엔진이 autoResizeEmbeddedInput=true 를 강제 설정(@spec)
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 값 읽기
    let autoResizeVal = con_autoResizeEmbeddedInput.getText(); // gdl_boolean : 라벨이 곧 값('' / 'true' / 'false')
    let accessibilityVal = con_accessibility.getValue();       // '' / 'true' / 'false'

    // 동작 조건/현재 설정 라벨 생성 (단일따옴표 금지, 줄바꿈 금지)
    $c.gcm.createLabel('label="컬럼 구성: col1=text(embeddedInput) / col2=secret(embeddedInput) / col3=calendar(embeddedInput) / col4=text(embeddedInput). 각 본문 컬럼 기본 너비 120px."', '', 'label1');
    $c.gcm.createLabel('label="현재 설정: autoResizeEmbeddedInput=' + (autoResizeVal === '' ? '미설정(기본 false)' : autoResizeVal) + ' / accessibility=' + (accessibilityVal === '' ? '미설정(기본 false)' : accessibilityVal) + '. [적용 옵션 확인] / [input 크기 조정 확인] 버튼으로 검증."', '', 'label2');
    $c.gcm.createLabel('label="[엔진 동작 참고] true=embedded input(text/secret)을 td 크기에 맞게 정밀 조정(셀 안). false/미설정=현재 엔진은 활성화(focus) 시에도 조정하지 않고 기본 크기 유지(가이드 @propval 의 활성화 시 조정 과 차이). calendar 는 옵션과 무관하게 항상 맞춤."', '', 'label3');

    // dataList 직접 생성 (4행). col3 은 calendar 용 yyyyMMdd 날짜
    let strNameSpace = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDl += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDl += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true">';
    let rows = [
        ['Apple',  '1234', '20251101', 'Alpha'],
        ['Banana', '5678', '20251102', 'Beta'],
        ['Cherry', '9012', '20251103', 'Gamma'],
        ['Date',   '3456', '20251104', 'Delta']
    ];
    for (let r = 0; r < rows.length; r++) {
        strDl += '<w2:row>';
        strDl += '<col1><![CDATA[' + rows[r][0] + ']]></col1>';
        strDl += '<col2><![CDATA[' + rows[r][1] + ']]></col2>';
        strDl += '<col3><![CDATA[' + rows[r][2] + ']]></col3>';
        strDl += '<col4><![CDATA[' + rows[r][3] + ']]></col4>';
        strDl += '</w2:row>';
    }
    strDl += '</w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);

    // autoResizeEmbeddedInput / accessibility 속성 (미설정 시 속성 미부여 = 기본값)
    let autoResizeAttr = autoResizeVal === '' ? '' : 'autoResizeEmbeddedInput="' + autoResizeVal + '" ';
    let accessibilityAttr = accessibilityVal === '' ? '' : 'accessibility="' + accessibilityVal + '" ';

    // target 생성 (Header inputType=text + Body embeddedInput Column 4개)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + autoResizeAttr + accessibilityAttr + 'checkAllType="false" dataList="data:dlt_bind" id="" style="width:700px;height:250px;">';
    strTarget += '<w2:caption style="" id="caption1" value="autoResizeEmbeddedInput 테스트 그리드"></w2:caption>';
    // Header : 모든 컬럼 inputType=text
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="120" inputType="text" id="hcol1" value="텍스트"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol2" value="시크릿"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol3" value="캘린더"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol4" value="텍스트2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    // Body : embeddedInput=true Column (text / secret / calendar / text)
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="120" inputType="text"   dataType="text" embeddedInput="true" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="secret" dataType="text" embeddedInput="true" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="120" inputType="calendar" dataType="date" embeddedInput="true" viewType="icon" displayMode="label" calendarFormat="yyyyMMdd" displayFormat="yyyy-MM-dd" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text"   dataType="text" embeddedInput="true" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 생성 직후 적용 옵션 자동 1회 출력
    scwin.btn_checkOption_onclick();
}



// 적용된 autoResizeEmbeddedInput 옵션값 확인
//  - accessibility=true 이면 엔진이 autoResizeEmbeddedInput 을 true 로 강제 설정(@spec, V5)
scwin.btn_checkOption_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let applied = scwin.target1.options.autoResizeEmbeddedInput;
    let acc = scwin.target1.options.accessibility;
    let conVal = con_autoResizeEmbeddedInput.getText();
    let accSet = con_accessibility.getValue();

    bottom.setReturnValue("[설정] autoResizeEmbeddedInput=" + (conVal === '' ? '미설정' : conVal) + " / accessibility=" + (accSet === '' ? '미설정' : accSet));
    bottom.setReturnValue("[적용 옵션] autoResizeEmbeddedInput = " + applied);
    if (acc === true) {
        bottom.setReturnValue("==> accessibility=true → autoResize 강제 true (V5)");
    }
}



// embeddedInput 의 Input 창 크기가 td(Cell) 크기에 맞게 자동 조정되었는지 확인
//  - autoResizeEmbeddedInput=true (또는 accessibility=true 강제) : 그리기 시점에 input 너비가 td 안쪽(td.clientWidth - padding)에 맞게 계산되어 td 를 넘지 않음 → 자동 조정됨
//  - false / 미설정 : input 크기를 td 에 맞게 자동 조정하지 않아 기본(intrinsic) 너비 유지(활성화해도 동일) → td 안쪽 너비보다 넓음 → 미조정
//  - 측정 대상 : col1(text) / col2(secret) / col3(calendar)
//    · text/secret : true 일때만 td 에 맞게 조정(변별 가능), false/미설정 은 미조정(기본 너비 유지)
//    · calendar : 옵션과 무관하게 항상 td 에 맞게 조정(변별 불가, 참고용 출력)
//  - setColumnWidth 경로는 옵션 무관 항상 재계산되므로 측정에서 제외
scwin.btn_resizeCheck_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let gridId = scwin.target1.id;
    let applied = scwin.target1.options.autoResizeEmbeddedInput;
    bottom.setReturnValue("[적용 옵션] autoResizeEmbeddedInput = " + applied);

    // Row0 의 각 컬럼 td 와 내부 input 요소 너비를 측정하는 헬퍼
    let measure = function (colId) {
        let colIdx = scwin.target1.getColumnIndex(colId);
        let td = document.querySelector("td[id*='" + gridId + "_cell_0_" + colIdx + "']");
        let input = td ? td.querySelector('input') : null;
        return { tdW: td ? td.clientWidth : 0, inputW: input ? input.offsetWidth : 0, hasInput: !!input };
    };

    // 측정 대상 컬럼 (text / secret / calendar)
    let targets = [
        { id: 'col1', label: 'text' },
        { id: 'col2', label: 'secret' },
        { id: 'col3', label: 'calendar', note: ' (옵션 무관 항상 조정)' }
    ];

    // 1) 기본 너비(120px) 상태에서 input 이 td 안쪽에 맞게 조정되었는지 판정
    //    - 조정됨 : input 너비 <= td 안쪽 너비 (td 를 넘지 않음)
    //    - 미조정 : input 너비 > td 안쪽 너비 (기본 너비 유지, td 초과)
    for (let i = 0; i < targets.length; i++) {
        let m = measure(targets[i].id);
        let fitted = m.hasInput && (m.inputW <= m.tdW);
        let verdict = fitted ? '자동 조정됨' : '미조정';
        bottom.setReturnValue('[' + targets[i].label + '] td=' + m.tdW + ' / input=' + m.inputW + ' → ' + verdict + (targets[i].note || ''));
    }
}
